create sequence if not exists public.production_seq start 1;
create table if not exists public.production_orders(id uuid primary key default gen_random_uuid(),production_number text unique not null default ('PRD-'||lpad(nextval('public.production_seq')::text,6,'0')),product_id uuid references public.products(id),order_type text not null default 'stock',planned_quantity numeric(14,3) not null default 0,actual_quantity numeric(14,3) not null default 0,damaged_quantity numeric(14,3) not null default 0,destination_warehouse_id uuid references public.warehouses(id),status text not null default 'draft',start_at timestamptz,end_at timestamptz,notes text,created_by uuid references public.profiles(id),approved_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table if not exists public.production_materials(id uuid primary key default gen_random_uuid(),production_id uuid not null references public.production_orders(id) on delete cascade,raw_material_id uuid references public.raw_materials(id),product_id uuid references public.products(id),item_name text not null,quantity numeric(14,3) not null,cost_price numeric(14,2) not null default 0);
create or replace function public.create_supplier(p_name text,p_phone text default null,p_company text default null,p_address text default null,p_materials text default null,p_notes text default null) returns public.suppliers language plpgsql security definer set search_path=public as $$declare s public.suppliers;begin if auth.uid() is null or not public.current_user_has_permission('purchases.create') then raise exception 'غير مصرح بإضافة مورد';end if;if nullif(btrim(p_name),'') is null then raise exception 'اسم المورد مطلوب';end if;insert into public.suppliers(name,company_name,phone,address,materials,notes,created_by) values(btrim(p_name),p_company,p_phone,p_address,p_materials,p_notes,auth.uid()) returning * into s;return s;end;$$;
create or replace function public.create_purchase_draft(p_supplier_id uuid,p_item_name text,p_quantity numeric,p_unit_name text,p_unit_price numeric,p_payment_method text default 'credit',p_paid_amount numeric default 0,p_notes text default null) returns public.purchases language plpgsql security definer set search_path=public as $$declare pur public.purchases;begin if auth.uid() is null or not public.current_user_has_permission('purchases.create') then raise exception 'غير مصرح بإضافة شراء';end if;if p_supplier_id is null or nullif(btrim(p_item_name),'') is null or p_quantity<=0 or p_unit_price<0 then raise exception 'أدخل المورد والصنف والكمية والسعر';end if;insert into public.purchases(supplier_id,total,paid_amount,payment_method,notes,created_by) values(p_supplier_id,p_quantity*p_unit_price,greatest(p_paid_amount,0),coalesce(nullif(p_payment_method,''),'credit'),p_notes,auth.uid()) returning * into pur;insert into public.purchase_items(purchase_id,item_name,quantity,unit_name,unit_price) values(pur.id,btrim(p_item_name),p_quantity,p_unit_name,p_unit_price);return pur;end;$$;
create or replace function public.create_production_order(p_product_id uuid,p_planned_quantity numeric,p_order_type text,p_destination uuid,p_notes text default null) returns public.production_orders language plpgsql security definer set search_path=public as $$declare po public.production_orders;begin if auth.uid() is null or not public.current_user_has_permission('production.create') then raise exception 'غير مصرح بإنشاء أمر إنتاج';end if;if p_product_id is null or p_planned_quantity<=0 then raise exception 'اختر المنتج والكمية';end if;insert into public.production_orders(product_id,planned_quantity,order_type,destination_warehouse_id,notes,created_by) values(p_product_id,p_planned_quantity,coalesce(nullif(p_order_type,''),'stock'),p_destination,p_notes,auth.uid()) returning * into po;return po;end;$$;
create or replace function public.create_return_draft(p_sale_id uuid,p_sale_item_id uuid,p_quantity numeric,p_good_quantity numeric,p_damaged_quantity numeric,p_inspection_quantity numeric,p_reason text default null) returns public.returns language plpgsql security definer set search_path=public as $$declare r public.returns;si public.sale_items;begin if auth.uid() is null or not public.current_user_has_permission('returns.create') then raise exception 'غير مصرح بإنشاء مرتجع';end if;select * into si from public.sale_items where id=p_sale_item_id and sale_id=p_sale_id;if si.id is null then raise exception 'بند الفاتورة غير موجود';end if;if p_quantity<=0 or p_quantity>si.quantity then raise exception 'كمية المرتجع غير صحيحة';end if;if greatest(p_good_quantity,0)+greatest(p_damaged_quantity,0)+greatest(p_inspection_quantity,0)<>p_quantity then raise exception 'قسّم كمية المرتجع بين صالح وتالف وفحص';end if;insert into public.returns(sale_id,subtotal,total,status,reason,created_by) values(p_sale_id,p_quantity*si.unit_price,p_quantity*si.unit_price,'draft',p_reason,auth.uid()) returning * into r;insert into public.return_items(return_id,sale_item_id,product_id,quantity,good_quantity,damaged_quantity,inspection_quantity,unit_price,line_total) values(r.id,si.id,si.product_id,p_quantity,p_good_quantity,p_damaged_quantity,p_inspection_quantity,si.unit_price,p_quantity*si.unit_price);return r;end;$$;
grant execute on function public.create_supplier(text,text,text,text,text,text) to authenticated;grant execute on function public.create_purchase_draft(uuid,text,numeric,text,numeric,text,numeric,text) to authenticated;grant execute on function public.create_production_order(uuid,numeric,text,uuid,text) to authenticated;grant execute on function public.create_return_draft(uuid,uuid,numeric,numeric,numeric,numeric,text) to authenticated;
grant usage,select on sequence public.production_seq to authenticated;grant select,insert,update,delete on public.production_orders,public.production_materials to authenticated;
alter table public.production_orders enable row level security;alter table public.production_materials enable row level security;create policy production_orders_access on public.production_orders for all to authenticated using(true) with check(true);create policy production_materials_access on public.production_materials for all to authenticated using(true) with check(true);
